def test_t01_fix1_memory_tool_legacy_ask_revision_change_restarts(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    auth, data_root, root, _store, _grant_a = _fix1_policy_fixture(
        monkeypatch, tmp_path
    )
    tool = MemoryTool()

    def ask() -> Any:
        return tool.run(
            root,
            operation="ask",
            subject=SUBJECT,
            query="needle",
            owner_scope=ALICE.as_dict(),
        )

    baseline = ask()
    assert baseline["status"] == "ok"
    assert len(_fix1_wire_rows(baseline)) == 3

    # A revision change that touches no field of this access (a second owner's
    # grant) does not restart the read.
    fired = _fix1_fire_after(
        monkeypatch,
        TypedArtifactStore,
        "search_rows",
        lambda: _grant(auth, root, BOB, data_root, ops=("ask",)),
    )
    unchanged = ask()
    assert fired["n"] == 1
    assert len(_fix1_wire_rows(unchanged)) == 3
    assert "E_RESTART" not in _dump(unchanged)

    # Revoking this owner's grant and granting it again mid-call (a new grant id)
    # restarts the read.
    def revoke_and_regrant() -> None:
        _fix1_revoke(auth, _grant_a, data_root)
        _grant(auth, root, ALICE, data_root)

    fired = _fix1_fire_after(
        monkeypatch,
        TypedArtifactStore,
        "search_rows",
        revoke_and_regrant,
    )
    restarted = ask()
    assert fired["n"] == 1
    assert _fix1_wire_rows(restarted) == []
    assert "mk-r" not in _dump(restarted)
    assert "E_RESTART" in _dump(restarted)


