def _g2_dashboard_context(env: _G2Env) -> tuple[str, Any]:
    from rush.dashboard.server import DashboardContext

    project_id = _g2_project_id(env)
    ctx = DashboardContext(
        {project_id: {"root": str(env.root), "name": "proj"}},
        bound_host="127.0.0.1",
        bound_port=0,
        data_root=env.data_root,
    )
    return project_id, ctx


def _g2_dashboard_sync(env: _G2Env) -> Any:
    from rush.dashboard import server

    project_id, ctx = _g2_dashboard_context(env)
    server._sync_current_map(ctx, project_id)
    record = ctx.projects.get(project_id)
    return (record.snapshot.get("memories") if record is not None else None) or []


def _g2_dashboard_promote(env: _G2Env, cell: _G2Cell) -> Any:
    from rush.dashboard import server

    project_id, ctx = _g2_dashboard_context(env)
    status, body = server._dispatch_memory_promote(
        ctx,
        project_id,
        {
            "subject": SUBJECT,
            "content": {"text": "needle mk-pro"},
            "source": "source-a",
            "owner_scope": ALICE.as_dict(),
        },
        {"cache_write": True},
    )
    if status != 200:
        raise _g2_denied_write(str(body.get("reason") or body.get("code")))
    return status, body


def _g2_dashboard_promote_check(
    env: _G2Env, cell: _G2Cell, out: _G2Out, before: Any
) -> None:
    assert out.body[0] == 200, out.body
    assert out.committed == 1, (out.committed, out.body)


#: dashboard POST operation -> its dispatcher (`_handle_action` routes `memory_<op>`)
_G2_DASHBOARD_MUTATIONS = {
    "edit": "_dispatch_memory_edit",
    "archive": "_dispatch_memory_archive",
    "delete": "_dispatch_memory_delete",
    "maintain": "_dispatch_memory_maintain",
}


def _g2_dashboard_mutation(spec: _G2Spec) -> _G2Route:
    """`spec`'s operation as the dashboard POST `memory_<operation>`: the arguments
    `_handle_action` hands the dispatcher (its `owner_scope` already normalized; the
    dispatcher keeps only the keys it forwards) and the dashboard's grants. `maintain`
    sends no `request`, so it has no preview form. A missing `cache_write` grant on an
    apply is the dashboard's own 403 `grant_denied`, before the tool runs."""
    dispatcher = _G2_DASHBOARD_MUTATIONS[spec.operation]
    apply = spec.cell.endswith("-apply")

    def call(env: _G2Env, cell: _G2Cell) -> _G2Out:
        from rush.dashboard import server

        kwargs = spec.kwargs(env, cell)
        if spec.operation == "maintain":
            arguments = {"task": kwargs["task"], "owner_scope": kwargs["owner_scope"]}
            if "missing_no_marker" in cell.row:
                # 72-T04 D3: `legacy` mode refuses a maintain that names no sources.
                arguments["sources"] = kwargs["sources"]
        else:
            arguments = dict(kwargs["request"])
        perms = _g2_permissions(cell, default_cache_write=spec.default_cache_write)
        grants = {
            "cache_write": perms.cache_write,
            "artifact_write": perms.artifact_write,
            "build": perms.build,
            "network": perms.network,
        }
        project_id, ctx = _g2_dashboard_context(env)
        try:
            _status, body = getattr(server, dispatcher)(
                ctx, project_id, arguments, grants
            )
        except server._ActionDenied as exc:
            return _G2Out(exc.code, exc.code, frozenset(), 0, str(exc), "error")
        return _g2_out_from_tool(body)

    supports = dict(spec.supports)
    if apply:
        supports["cache_write"] = {
            **spec.supports["cache_write"],
            "off": _ex("grant_denied", status="error", committed=0),
        }
    server_py = "dashboard/server.py"
    refresh = (
        "_refresh_project_memories"
        if spec.operation == "maintain"
        else "_refresh_project_memories_if_store_exists"
    )
    return _G2Route(
        transport="dashboard",
        key="dashboard_mutations",
        cell=f"dashboard-operation-memory_{spec.operation}-apply-{spec.cell.rsplit('-', 1)[1]}",
        op=spec.op,
        call=call,
        supports=supports,
        missing_ops=spec.missing_ops,
        setup=spec.setup,
        ok_codes=spec.ok_codes,
        owner_required=spec.owner_required,
        writer_family=spec.writer_family,
        check_ok=spec.check_ok,
        check_legacy=spec.check_legacy,
        ungranted=spec.ungranted,
        idempotent=spec.idempotent,
        covers=((server_py, dispatcher), (server_py, refresh)),
        intrinsic_apply=spec.intrinsic_apply,
        ignore_data=_G2_DASHBOARD_DATA,
    )


def _g2_dashboard_post_routes() -> list[_G2Route]:
    server_py = "dashboard/server.py"
    promote = dataclasses.replace(
        _g2_writer(
            "dashboard_mutations",
            "dashboard-operation-memory_promote",
            "source-a",
            _g2_dashboard_promote,
            covers=(
                (server_py, "_dispatch_memory_promote"),
                (server_py, "_refresh_project_memories_if_store_exists"),
                (server_py, "_refresh_project_memories"),
            ),
            check=_g2_dashboard_promote_check,
            sources=(),
        ),
        grant_owner="alice",
    )
    sync = _g2_reader(
        "dashboard_readers",
        "dashboard_readers-function-sync_current_map",
        _g2_dashboard_sync,
        _g2_ids("mem"),
        frozenset({"mem:a1", "mem:a2", "mem:arch", "mem:exp", "mem:tam"}),
        covers=(
            (server_py, "_sync_current_map"),
            (server_py, "_refresh_project_memories"),
        ),
        legacy=frozenset(
            {"mem:a1", "mem:a2", "mem:x1", "mem:arch", "mem:exp", "mem:tam"}
        ),
        op="list",
    )
    # `_refresh_project_memories` reads `snapshot_memories`, a reference inventory
    # (plan L318): it lists a rejected/pending row as it lists an archived one
    sync = dataclasses.replace(
        sync,
        check_ok=_g2_shown_qualified(
            frozenset({"mem:a1", "mem:a2", "mem:arch", "mem:exp", "mem:tam"}),
            frozenset({"mem:rej", "mem:pen"}),
        ),
    )
    mutations = [
        _g2_dashboard_mutation(spec)
        for spec in _g2_all_specs()
        if spec.operation in _G2_DASHBOARD_MUTATIONS
        and not (spec.operation == "maintain" and spec.cell.endswith("-preview"))
    ]
    return [
        _g2_as("dashboard", promote, ignore_data=_G2_DASHBOARD_DATA),
        _g2_as("dashboard", sync, ignore_data=_G2_DASHBOARD_DATA),
        *mutations,
    ]


def _g2_scan_root(root: Path) -> str:
    return str(root)


def _g2_pre_scan(env: _G2Env) -> None:
    """The finished scan run a handoff is prepared from (files only, no store)."""
    (env.root / "app.py").write_text("def unreviewed():\n    pass\n", encoding="utf-8")
    _scan_manifest(env.root, "run-1")


def _g2_handoff_call(env: _G2Env, **kwargs: Any) -> Any:
    from rush.workflows.project_run import build_handoff

    return build_handoff(
        _g2_project_id(env), "run-1", "codex-cli", data_root=env.data_root, **kwargs
    )


def _g2_scan_denied(exc: Exception) -> Exception:
    return _g2_denied_write(str(exc).rsplit(": ", 1)[-1])


def _g2_build_handoff(env: _G2Env, cell: _G2Cell) -> Any:
    from rush.workflows.project_run import ScanHandoffAuthError

    try:
        return _g2_handoff_call(env)
    except ScanHandoffAuthError as exc:
        raise _g2_scan_denied(exc) from exc


def _g2_build_check(env: _G2Env, cell: _G2Cell, out: _G2Out, before: Any) -> None:
    assert out.body.state == "prepared", out.body
    assert out.committed == 1, out.committed


def _g2_setup_prepared(env: _G2Env) -> None:
    """A handoff prepared under the row's own grant (a session prepared before any
    grant has no bound sender and is refused in `policy` mode), or none when the grant
    does not allow preparing one."""
    from rush.workflows.project_run import ScanHandoffAuthError

    try:
        env.extra["handoff"] = _g2_handoff_call(
            env,
            operation_id="g2-op",
            effect_ids={
                "artifact_create": "g2-artifact",
                "session_create": "g2-session",
                "delivery_transition": "g2-delivery",
            },
            owner_instance_id="",
        )
    except ScanHandoffAuthError:
        env.extra["handoff"] = None


def _g2_dispatch_handoff(env: _G2Env, cell: _G2Cell) -> Any:
    from rush.memory.handoff import HandoffError
    from rush.workflows.project_run import (
        ScanHandoffAuthError,
        ScanInvalidRequestError,
        dispatch_handoff,
    )

    handoff = env.extra.get("handoff")
    if handoff is None:
        raise _g2_denied_write("no_handoff")
    try:
        return dispatch_handoff(
            _g2_project_id(env),
            handoff.handoff_id,
            handoff.session_capability,
            data_root=env.data_root,
        )
    except (ScanHandoffAuthError, HandoffError, ScanInvalidRequestError) as exc:
        raise _g2_scan_denied(exc) from exc


def _g2_dispatch_check(env: _G2Env, cell: _G2Cell, out: _G2Out, before: Any) -> None:
    assert out.body.state == "delivered", out.body


def _g2_recover_handoff(env: _G2Env, cell: _G2Cell) -> Any:
    from rush.workflows.project_run import (
        ScanInvalidRequestError,
        recover_prepared_handoff,
    )

    handoff = env.extra.get("handoff")
    if handoff is None:
        raise _g2_denied_write("no_handoff")
    try:
        recovered = recover_prepared_handoff(
            _g2_project_id(env),
            handoff.handoff_id,
            claimed_operation_id="g2-op",
            artifact_create_receipt_id="g2-artifact",
            session_create_receipt_id="g2-session",
            delivery_receipt_id="g2-delivery",
            data_root=env.data_root,
        )
    except ScanInvalidRequestError as exc:
        raise _g2_scan_denied(exc) from exc
    if recovered is None:
        raise _g2_denied_write("not_recovered")
    return recovered


def _g2_recover_check(env: _G2Env, cell: _G2Cell, out: _G2Out, before: Any) -> None:
    assert out.body.state == "delivered", out.body


def _g2_scan_dims() -> dict[str, dict[str, _G2Expect]]:
    """A prepared handoff needs a store: without one (or with a pre-72 one) the route
    refuses and changes nothing."""
    return {
        "store": {
            "absent": _ex("E_PERMISSION", committed=0, absent=(".rush/memory.db",)),
            "old_schema": _ex("E_PERMISSION", committed=0),
        }
    }


def _g2_scan_routes() -> list[_G2Route]:
    run_py = "workflows/project_run.py"
    common: dict[str, Any] = {"sources": (_g2_scan_root,)}
    build = _g2_writer(
        "scan_handoff",
        "scan_handoff-function-build_handoff",
        "scan",
        _g2_build_handoff,
        covers=((run_py, "build_handoff"),),
        check=_g2_build_check,
        pre_setup=_g2_pre_scan,
        **common,
    )
    dispatch = _g2_writer(
        "scan_handoff",
        "scan_handoff-function-dispatch_handoff",
        "scan",
        _g2_dispatch_handoff,
        covers=((run_py, "dispatch_handoff"),),
        check=_g2_dispatch_check,
        committed=0,
        pre_setup=_g2_pre_scan,
        supports=_g2_scan_dims(),
        **common,
    )
    recover = _g2_writer(
        "scan_handoff",
        "scan_handoff-function-recover_prepared_handoff",
        "scan",
        _g2_recover_handoff,
        covers=((run_py, "recover_prepared_handoff"),),
        check=_g2_recover_check,
        committed=0,
        pre_setup=_g2_pre_scan,
        supports=_g2_scan_dims(),
        **common,
    )
    # The scan handoff is dashboard-driven (`handoff_send`): its project is addressed
    # by id, so the overlay row registers it as fixture state like every dashboard route.
    return [
        dataclasses.replace(
            build,
            transport="dashboard",
            overlay_setup=_g2_pre_scan,
            missing_ops=("expand",),
        ),
        dataclasses.replace(
            dispatch,
            transport="dashboard",
            setup=_g2_setup_prepared,
            missing_ops=("expand",),
        ),
        dataclasses.replace(
            recover,
            transport="dashboard",
            setup=_g2_setup_prepared,
            missing_ops=("expand",),
            ignore_db=True,
        ),
    ]


def _g2_setup_reconcile(env: _G2Env) -> None:
    """A dead owner's admission row and the handoff it left prepared (under the row's
    own grant, so its sender is bound), in a ledger outside the project and data root."""
    from rush.dashboard.state import MutationLedger
    from rush.workflows.project_run import (
        ScanHandoffAuthError,
        ScanInvalidRequestError,
    )

    project_id = _g2_project_id(env)
    ledger = MutationLedger(db_path=env.tmp_path / "admission.db")
    effect_ids = {
        "artifact_create": "g2-artifact",
        "session_create": "g2-session",
        "delivery_transition": "g2-delivery",
    }
    reservation = ledger.reserve(
        project_id,
        "g2-handoff",
        "",
        operation_type="handoff_send",
        effect_ids=effect_ids,
    )
    ledger.admit(
        project_id,
        execution_identity="scan_start:g2",
        slot_id=reservation.operation_id,
        operation_id=reservation.operation_id,
        run_id="run-1",
        plan_id="g2-plan",
        owner_instance_id="g2-dead-owner",
    )
    env.extra["ledger"] = ledger
    try:
        env.extra["handoff"] = _g2_handoff_call(
            env,
            operation_id=reservation.operation_id,
            effect_ids=effect_ids,
            owner_instance_id="g2-dead-owner",
        )
    except (ScanHandoffAuthError, ScanInvalidRequestError):
        env.extra["handoff"] = None


def _g2_setup_reconcile_overlay(env: _G2Env) -> None:
    _g2_pre_scan(env)
    _g2_setup_reconcile(env)


def _g2_reconcile(env: _G2Env, cell: _G2Cell) -> Any:
    from rush.dashboard.state import reconcile_admissions
    from rush.workflows.project_run import _load_handoff

    ledger = env.extra.get("ledger")
    if ledger is None:
        raise _g2_denied_write("no_ledger")
    reconciled = reconcile_admissions(ledger, data_root=env.data_root)
    handoff = env.extra.get("handoff")
    loaded = _load_handoff(env.root, handoff.handoff_id) if handoff else None
    return reconciled, (loaded.state if loaded is not None else None)


def _g2_reconcile_check(env: _G2Env, cell: _G2Cell, out: _G2Out, before: Any) -> None:
    assert out.body == (1, "delivered"), out.body


def _g2_reconcile_route() -> _G2Route:
    """The dead owner's handoff is delivered exactly where its grant allows (the
    success oracle); a refusing row reconciles the admission, delivers nothing and
    leaves every file as it was (the exposure-reducing db cleanup aside)."""
    state_py = "dashboard/state.py"
    base = _g2_writer(
        "dashboard_admission_reconcile",
        "dashboard_admission_reconcile-function-reconcile_admissions",
        "scan",
        _g2_reconcile,
        covers=((state_py, "reconcile_admissions"),),
        check=_g2_reconcile_check,
        committed=0,
        pre_setup=_g2_pre_scan,
        sources=(_g2_scan_root,),
        supports={
            "store": {
                "absent": _ex("E_PERMISSION", committed=0, absent=(".rush/memory.db",)),
                "old_schema": _ex(None, committed=0, check=None),
            }
        },
    )
    return dataclasses.replace(
        base,
        transport="dashboard",
        setup=_g2_setup_reconcile,
        overlay_setup=_g2_setup_reconcile_overlay,
        missing_ops=("expand",),
        ignore_data=_G2_DASHBOARD_DATA,
        ignore_db=True,
    )


def _g2_overview_shows(result: Any) -> set[str]:
    return _g2_ids("ov")(_rd(result))


def _g2_extra_routes() -> list[_G2Route]:
    from rush.tools.memory import memory_overview

    overview = _g2_reader(
        "overview",
        "overview-function-memory_overview",
        lambda env: memory_overview(env.root),
        _g2_overview_shows,
        frozenset({"ov:a1", "ov:a2", "ov:tam"}),
        covers=(("tools/memory.py", "memory_overview"),),
        op="list",
        legacy=frozenset({"ov:a1", "ov:a2", "ov:tam", "ov:x1"}),
        old_schema_reads=True,
    )
    return [
        *_g2_origin_routes(),
        *_g2_cli_text_routes(),
        *_g2_tui_routes(),
        *_g2_dashboard_post_routes(),
        *_g2_scan_routes(),
        _g2_reconcile_route(),
        overview,
    ]


def _g2_tool_routes() -> list[_G2Route]:
    specs = _g2_all_specs()
    return [
        *(_g2_inproc(spec) for spec in specs),
        *(route for spec in specs if (route := _g2_mcp(spec)) is not None),
        *(
            _g2_bridge(spec)
            for spec in specs
            if spec.operation in _G2_BRIDGE_OPERATIONS
        ),
        *_g2_producer_routes(),
        *(_g2_cli_generic(spec) for spec in specs if spec.operation in _G2_CLI_GENERIC),
        *_g2_cli_explicit_routes(),
        *_g2_writer_routes(),
        *_g2_reader_routes(),
        *_g2_telemetry_routes(),
        *_g2_visible_routes(),
        *_g2_continuity_routes(),
        *_g2_dashboard_routes(),
        *_g2_extra_routes(),
    ]


_G2_ROUTES: list[_G2Route] = _g2_tool_routes()


# --- R8 (route x mode matrix): the internal-module entry points ------------------------
#
# One `_G2Route` per entry point of the mutation view, the intent and recipe modules, the
# maintenance and expiry sweeps and the D4 gate helpers. Id grammar:
# `internal.<route>-function-<name>-<dimension>-<value>...`. A dimension an internal
# function does not vary along is a byte-identical cell (the same result as the baseline
# call, store and file digests unchanged); the ones it does vary along assert the
# observed outcome.

_R8_DENY = (
    "grant-revoked",
    "owner-omitted",
    "policy_state-invalid",
    "missing_one",
    "missing_marker",
    "source-ungranted",
)
_R8_STATES = ("active", "archived", "expired", "tampered")
#: the rows 72-T05 marks `rejected` / `pending` (not current, still stored)
_R8_NARROWED = ("rejected", "pending")
_R8_ALL_STATES = (*_R8_STATES, *_R8_NARROWED)


def _r8_denied_row(cell: _G2Cell) -> bool:
    return cell.row.endswith(_R8_DENY)


def _r8_sql(env: _G2Env, sql: str, *args: Any) -> None:
    assert env.store is not None
    with contextlib.closing(sqlite3.connect(env.store.db_path)) as conn:
        conn.execute(sql, args)
        conn.commit()
    gc.collect()


def _r8_state(env: _G2Env, artifact_id: str) -> None:
    """Put one fixture row in the cell's `row_state` (taken in legacy mode)."""
    state = env.extra["cell"].row_state
    if env.store is None or state in (None, "active"):
        return
    if state == "tampered":
        _tamper(env.store.db_path, artifact_id)
        gc.collect()
    elif state == "archived":
        _r8_sql(
            env,
            "UPDATE memory_artifacts SET archived_at = 1.0 WHERE id = ?",
            artifact_id,
        )
    elif state == "expired":
        _r8_sql(
            env,
            "UPDATE memory_artifacts SET expires_at = 1.0, expired_at = 2.0, "
            "expired_by = 'sweep' WHERE id = ?",
            artifact_id,
        )


def _r8_narrow(env: _G2Env, artifact_id: str) -> None:
    """Mark one fixture row `rejected` / `pending` (a `row_state-rejected` / `-pending`
    cell), the way `_g2_seed` does: through the store, so the row's MAC covers the
    applicability. The row keeps the exact content its own writer produced."""
    state = env.extra["cell"].row_state
    if env.store is None or state not in _R8_NARROWED:
        return
    current = env.store.get_current(artifact_id)
    assert current is not None, artifact_id
    _r8_sql(
        env, "DELETE FROM memory_artifact_versions WHERE artifact_id = ?", artifact_id
    )
    _r8_sql(env, "DELETE FROM memory_artifacts WHERE id = ?", artifact_id)
    written = env.store.write(dataclasses.replace(current, applicability=state))
    assert written.artifact_version == 1 and written.applicability == state, written


def _r8_stored(env: _G2Env, artifact_id: str) -> dict[str, Any]:
    """The raw current row `artifact_id` as stored (applicability, stale, expiry)."""
    assert env.store is not None
    with contextlib.closing(sqlite3.connect(env.store.db_path)) as conn:
        conn.row_factory = sqlite3.Row
        row = conn.execute(
            "SELECT * FROM memory_artifacts WHERE id = ?", (artifact_id,)
        ).fetchone()
    assert row is not None, artifact_id
    return dict(row)


def _r8_live(env: _G2Env, cell: _G2Cell) -> bool:
    """Whether the reader sees its fixture row as current: a rejected or pending row
    is stored but not current, so the reader answers "unknown" like an archived one."""
    return (
        cell.store == "present"
        and cell.row_state in (None, "active")
        and (env.root / ".rush" / "memory.db").exists()
    )


def _r8_expect(env: _G2Env, cell: _G2Cell, value: Any, unknown: Any, ok: Any) -> Any:
    if _r8_denied_row(cell) or not _r8_live(env, cell):
        assert value == unknown, (cell.row, value)
    else:
        assert ok(value), (cell.row, value)
    return value


def _r8_denial_out(denial: Any) -> _G2Out:
    return _G2Out("E_PERMISSION", denial.reason, frozenset(), 0, None)


def _r8_out(call: Any) -> _G2Out:
    """An internal call as an outcome: a `RouteDenial` or an access refusal is an
    `E_PERMISSION`, any other raised exception its class name."""
    from rush.memory.retrieval import RouteDenial

    try:
        value = _g2_guarded(call)
    except AssertionError:
        raise
    except Exception as exc:  # noqa: BLE001 - the exception class is the outcome
        reason = getattr(exc, "reason", None)
        if type(exc).__name__ == "MaintenanceAccessDenied":
            return _G2Out(
                "E_PERMISSION", reason or "policy_grant_required", frozenset()
            )
        return _G2Out(type(exc).__name__, None, frozenset(), 0, repr(exc))
    if isinstance(value.body, _G2Out):
        return value.body
    if isinstance(value.body, RouteDenial):
        return _r8_denial_out(value.body)
    return value


def _r8_route(key: str, name: str, call: Any, **extra: Any) -> _G2Route:
    extra.setdefault("op", "ask")
    extra.setdefault("takes_owner", False)
    extra.setdefault("coded", False)
    extra.setdefault("ok_codes", frozenset({None}))
    extra.setdefault("grant_owner", "project")
    return _G2Route(
        transport="internal",
        key=key,
        cell=f"{key}-function-{name}",
        call=lambda env, c: _r8_out(lambda: call(env, c)),
        **extra,
    )


def _r8_dump(env: _G2Env) -> list[str]:
    """Every stored row (current and version history) with only the generated ids,
    timestamps, digests and the project path normalized: what a writer committed."""
    db = env.root / ".rush" / "memory.db"
    if not db.exists():
        return []
    rows: list[str] = []
    with contextlib.closing(sqlite3.connect(db)) as conn:
        conn.row_factory = sqlite3.Row
        for table, order in (
            ("memory_artifacts", "id"),
            ("memory_artifact_versions", "artifact_id, artifact_version"),
        ):
            rows.extend(
                _g2_exact_body(env, {"table": table, **dict(row)})
                for row in conn.execute(f"SELECT * FROM {table} ORDER BY {order}")
            )
    gc.collect()
    return rows


def _r8_baseline_dump(route: _G2Route, env: _G2Env, row: str) -> list[str]:
    """The rows the baseline call commits: the same call over a fresh project with the
    same fixture and grant, under its own data root (so the row's own policy damage,
    an invalid policy file, cannot reach it). The overlay row's root is an empty
    storage root, so its baseline is the same call over a fresh empty root."""
    cell = _g2_parse_row(G2_POLICY_ROWS[0])
    base_tmp = env.tmp_path / "r8-baseline"
    base_tmp.mkdir()
    with env.monkeypatch.context() as mp:
        data_root = _fix1_data_root(mp, base_tmp)
        if row == G2_OVERLAY_ROW:
            empty = base_tmp / "empty"
            empty.mkdir()
            base = dataclasses.replace(
                env,
                root=empty.resolve(),
                data_root=data_root,
                store=None,
                tmp_path=base_tmp,
                monkeypatch=mp,
                extra={"cell": cell, "transport": route.transport},
            )
        else:
            base = _g2_env(base_tmp, mp, route, G2_POLICY_ROWS[0])
        route.call(base, cell)
        return _r8_dump(base)


def _r8_same_write(ok: Any):
    """These writers take no access (denial is `MemoryTool`'s, plan 2.3): every policy
    row, denial rows included, commits exactly the rows the baseline call commits (the
    overlay row points the call at an empty storage root, where its rows are those of
    the same call over a fresh empty root)."""

    def check(
        route: _G2Route, row: str, env: _G2Env, cell: _G2Cell, out: _G2Out
    ) -> None:
        assert out.code is None and isinstance(out.body, dict), (row, out.code)
        if row != G2_OVERLAY_ROW:
            assert ok(out.body), (row, out.body)
        assert _r8_dump(env) == _r8_baseline_dump(route, env, row), row

    return check


def _r8_writer(key: str, name: str, source: str, call: Any, **extra: Any) -> _G2Route:
    """A writer: the grant approves `source`, the route owns the project owner."""
    extra.setdefault("op", "write")
    extra.setdefault("idempotent", False)
    check = extra.pop("check", None) or _g2_committed(extra.pop("committed", 1))
    dims = extra.pop("supports", None) or _g2_writer_dims(check)
    extra.setdefault("check_legacy", check)
    return _r8_route(
        key,
        name,
        call,
        supports=dims,
        grant_sources=(source,),
        owner_fixed=True,
        check_ok=check,
        custom_policy=_r8_same_write(
            extra.pop("ok", lambda body: body.get("code") == "OK")
        ),
        ignore=(".rush",),
        ignore_data=("user",),
        ignore_db=True,
        **extra,
    )


_R8_STATES_OK = {s: _ex(None) for s in _R8_ALL_STATES}
_R8_STORE_NONE = {
    "absent": _ex(None, absent=(".rush/memory.db",)),
    "old_schema": _ex(None),
}

# --- mutation view (tools/memory.py) -------------------------------------------------


def _r8_mv_call(env: _G2Env, cell: _G2Cell) -> Any:
    from rush.tools import memory as tools_memory

    preview = cell.apply == "preview"
    committed = (
        []
        if preview
        else [{"id": cell.target, "revision": 1, "source": "source-a", "kind": "write"}]
    )
    result = tools_memory._with_mutation_view(
        env.root, {"status": "ok", "raw": {"applied": not preview}}, committed
    )
    return result["raw"]


def _r8_mv_preview(env: _G2Env, cell: _G2Cell, out: _G2Out, before: Any) -> None:
    assert out.body == {
        "applied": False,
        "unchanged": "preview only (apply=false); nothing committed",
    }, out.body


def _r8_mv_applied(env: _G2Env, cell: _G2Cell, out: _G2Out, before: Any) -> None:
    body = out.body
    target = cell.target
    assert body["applied"] is True and body["changed"][target] == {
        "revision": 1,
        "kind": "write",
    }, body
    assert target in body["readback"], body


def _r8_mv_row(env: _G2Env, cell: _G2Cell, out: _G2Out, before: Any) -> None:
    _r8_mv_applied(env, cell, out, before)
    entry = out.body["readback"][cell.target]
    if cell.row_state in _R8_NARROWED:
        # the readback lists the stored row; the mark is the row's, it is not current
        assert _r8_stored(env, cell.target)["applicability"] == cell.row_state
        assert entry == {
            "present": True,
            "archived": False,
            "revision": 1,
            "subject": SUBJECT,
            "trust_tier": "DERIVED",
            "source": "source-a",
        }, entry
        return
    assert entry["source"] == "source-a" or entry["present"] is False, entry
    if cell.target == "arch":
        assert entry["archived"] is True, entry


_R8_ATTR_REFS = [{"id": "ghost", "version": 1, "source": "source-a"}]


def _r8_mv_attribution(env: _G2Env, cell: _G2Cell) -> Any:
    """The receipts of one read result: a ref that carries its `source` is kept as is;
    one without is resolved from the store's version history, else dropped."""
    from rush.tools import memory as tools_memory

    committed = (
        []
        if cell.apply == "preview"
        else [{"id": cell.target, "revision": 1, "source": "source-a", "kind": "write"}]
    )
    # `(target, 99)` has no stored version: it carries no source and resolves to none
    items = [
        {"id": cell.target, "version": 1},
        {"id": cell.target, "version": 99},
        *_R8_ATTR_REFS,
    ]
    return tools_memory._memory_attribution(
        env.root,
        "write",
        {"status": "ok", "raw": {"schema_version": 2, "items": items}},
        committed,
    )


def _r8_attr_check(env: _G2Env, cell: _G2Cell, out: _G2Out, before: Any) -> None:
    """Refs that carry no `source` are resolved from the store's version history; one
    that resolves to none is dropped. The version history survives `old_schema` (it
    lacks only the payload columns), so only the absent store resolves nothing."""
    from rush.memory.store import artifact_version_sources

    refs = [(cell.target, 1), (cell.target, 99)]
    sources = artifact_version_sources(env.root, refs)
    if cell.store == "absent":
        assert sources == {}, sources
    else:
        assert sources == {(cell.target, 1): "source-a"}, sources
    block = out.body
    assert block is not None and block["version"] == 1, block
    assert {(r["id"], r["revision"]) for r in block["used"]} == {
        ("ghost", 1),
        *((i, v) for (i, v) in sources),
    }, block
    assert {r["id"] for r in block["written"]} == (
        set() if cell.apply == "preview" else {cell.target}
    ), block


def _r8_mutation_routes() -> list[_G2Route]:
    mv_supports = {
        "apply": {
            "preview": _ex(None, check=_r8_mv_preview),
            "apply": _ex(None, check=_r8_mv_applied),
        },
        "store": {
            "absent": _ex(None, check=_r8_mv_applied, same=False, memory_same=False),
            "old_schema": _ex(
                None, check=_r8_mv_applied, same=False, memory_same=False
            ),
        },
        "row_state": {s: _ex(None, check=_r8_mv_row) for s in _R8_ALL_STATES},
    }
    attr_supports = {
        "apply": {s: _ex(None, check=_r8_attr_check) for s in ("preview", "apply")},
        "store": {s: _ex(None, check=_r8_attr_check) for s in ("absent", "old_schema")},
        "row_state": {s: _ex(None, check=_r8_attr_check) for s in _R8_ALL_STATES},
    }
    return [
        _r8_route(
            "mutation_view",
            "_with_mutation_view",
            _r8_mv_call,
            supports=mv_supports,
            ungated=frozenset(),
            covers=(("tools/memory.py", "_with_mutation_view"),),
        ),
        _r8_route(
            "mutation_view",
            "_memory_attribution",
            _r8_mv_attribution,
            supports=attr_supports,
            ungated=frozenset(),
            covers=(("tools/memory.py", "_memory_attribution"),),
        ),
    ]


# --- intent module (memory/intent.py) ------------------------------------------------

_R8_UNKNOWN_INTENT = {"code": "E_INPUT", "message": "unknown intent 'i1'"}
_R8_UNKNOWN_RECIPE = {"code": "E_INPUT", "message": "unknown recipe 'r1'"}
_R8_HELPER = {"path": "helper.py", "symbol": "helper"}


def _r8_seed_intent(env: _G2Env) -> None:
    if env.extra["cell"].store == "absent":
        return
    from rush.memory.intent import record_intent

    result = record_intent(project_root=env.root, intent_id="i1", behavior_id="b1")
    assert result.get("code") not in ("E_INPUT", "E_VERSION"), result
    _r8_state(env, "i1")
    _r8_narrow(env, "i1")


def _r8_seed_recipe(env: _G2Env) -> None:
    if env.extra["cell"].store == "absent":
        return
    from rush.memory.recipes import record_recipe

    result = record_recipe(
        project_root=env.root, recipe_id="r1", purpose="p", helper_ref=_R8_HELPER
    )
    assert result.get("code") not in ("E_INPUT", "E_VERSION"), result
    _r8_state(env, "r1")
    _r8_narrow(env, "r1")


def _r8_seed_superseding(env: _G2Env) -> None:
    if env.extra["cell"].store == "absent":
        return
    from rush.memory.intent import record_intent

    assert env.store is not None
    _row(env.store, "st1", None, "mk-st1")
    env.store.promote("st1", user_stated=True, expected_version=1)
    result = record_intent(project_root=env.root, intent_id="w1", behavior_id="b1")
    assert result.get("code") not in ("E_INPUT", "E_VERSION"), result
    _r8_state(env, "w1")
    _r8_narrow(env, "w1")


def _r8_check_intent(env: _G2Env, cell: _G2Cell) -> Any:
    from rush.memory.intent import check_intent

    value = check_intent(project_root=env.root, intent_id="i1")
    return _r8_expect(
        env, cell, value, _R8_UNKNOWN_INTENT, lambda v: v.get("code") == "UNRESOLVED"
    )


def _r8_resolve_recipe(env: _G2Env, cell: _G2Cell) -> Any:
    from rush.memory.recipes import resolve_recipe

    value = resolve_recipe(project_root=env.root, recipe_id="r1")
    return _r8_expect(
        env, cell, value, _R8_UNKNOWN_RECIPE, lambda v: v.get("code") != "E_INPUT"
    )


def _r8_seed_statement(env: _G2Env) -> None:
    """`row_state-rejected` / `-pending`: the fixture rows are all DERIVED, so the
    resolver would answer `None` on trust alone. Add a `STATED` statement `st1` (the
    way `_r8_seed_superseding` does) and narrow it, so the cell shows what the
    applicability does to an otherwise-authorizing row."""
    cell = env.extra["cell"]
    if cell.store == "absent" or cell.row_state not in _R8_NARROWED:
        return
    assert env.store is not None
    _row(env.store, "st1", None, "mk-st1")
    _r8_narrow(env, "st1")
    env.store.promote("st1", user_stated=True, expected_version=1)


def _r8_resolve_statement(env: _G2Env, cell: _G2Cell) -> Any:
    from rush.memory.intent import _resolve_authorized_statement

    target, version = ("st1", 2) if cell.row_state in _R8_NARROWED else (cell.target, 1)
    return _resolve_authorized_statement(env.root, {"id": target, "version": version})


def _r8_statement_state(env: _G2Env, cell: _G2Cell, out: _G2Out, before: Any) -> None:
    """`tampered` (a DERIVED fixture row): `None`. `rejected` / `pending` `st1` (STATED,
    promoted at version 2): not a currently-STATED statement (plan L51/L55: a
    rejected/pending row is not usable as current), so `None` too, and the row stays
    stored as it was. A second call gives the same answer, and the effects check
    proves nothing was written."""
    assert out.body is None, out.body
    assert _r8_resolve_statement(env, cell) is None
    if cell.row_state in _R8_NARROWED:
        stored = _r8_stored(env, "st1")
        assert (stored["trust_tier"], stored["artifact_version"]) == ("STATED", 2)
        assert stored["applicability"] == cell.row_state, stored


def _r8_record_intent(env: _G2Env, cell: _G2Cell) -> Any:
    from rush.memory.intent import record_intent

    return record_intent(project_root=env.root, intent_id="w1", behavior_id="b1")


def _r8_supersede(env: _G2Env, cell: _G2Cell) -> Any:
    from rush.memory.intent import supersede_intent

    return supersede_intent(
        project_root=env.root,
        intent_id="w1",
        expected_old_version=1,
        new_statement_ref={"id": "st1", "version": 2},
    )


def _r8_superseded(env: _G2Env, cell: _G2Cell, out: _G2Out, before: Any) -> None:
    row = _g2_row(env, "w1")
    assert row is not None and int(row["artifact_version"]) == 2, out.body


def _r8_record_recipe(env: _G2Env, cell: _G2Cell) -> Any:
    from rush.memory.recipes import record_recipe

    return record_recipe(
        project_root=env.root, recipe_id="w1", purpose="p", helper_ref=_R8_HELPER
    )


def _r8_seed_outcome(env: _G2Env) -> None:
    if env.extra["cell"].store == "absent":
        return
    from rush.memory.recipes import record_recipe

    assert env.store is not None
    _row(
        env.store,
        "ev1",
        None,
        "mk-ev1",
        content={"evidence_kind": "sandbox_verification", "outcome": "completed"},
    )
    result = record_recipe(
        project_root=env.root, recipe_id="w1", purpose="p", helper_ref=_R8_HELPER
    )
    assert result.get("code") not in ("E_INPUT", "E_VERSION"), result
    _r8_state(env, "w1")
    _r8_narrow(env, "w1")


def _r8_recipe_outcome(env: _G2Env, cell: _G2Cell) -> Any:
    from rush.memory.recipes import record_recipe_outcome

    return record_recipe_outcome(
        project_root=env.root,
        recipe_id="w1",
        recipe_version=1,
        patch_hash="a" * 64,
        verifier_receipt_ref={"id": "ev1", "version": 1},
    )


_R8_OUTCOME_OK = {
    "code": "OK",
    "id": "w1",
    "version": 2,
    "recipe_id": "w1",
    "passed": True,
    "receipt_ref": {"id": "ev1", "version": 1},
    "outcomes_count": 1,
}


def _r8_outcome_recorded(env: _G2Env, cell: _G2Cell, out: _G2Out, before: Any) -> None:
    """The baseline commits one passing outcome against the `sandbox_verification`
    receipt `ev1`: the recipe moves to version 2 and carries the outcome."""
    assert out.body == _R8_OUTCOME_OK, out.body
    row = _g2_row(env, "w1")
    assert row is not None and int(row["artifact_version"]) == 2, out.body


def _r8_outcome_store(env: _G2Env, cell: _G2Cell, out: _G2Out, before: Any) -> None:
    if cell.store == "absent":  # no store, so no recipe: nothing to append to
        assert out.body == {"code": "E_INPUT", "message": "unknown recipe 'w1'"}
    else:
        _r8_outcome_recorded(env, cell, out, before)


_R8_SUPERSEDED_OK = {
    "behavior_id": "b1",
    "code": "OK",
    "id": "w1",
    "intent_id": "w1",
    "statement_ref": {"id": "st1", "version": 2},
    "status": "confirmed",
    "supersedes_version": 1,
    "version": 2,
}


def _r8_narrowed_write(expected: dict[str, Any]) -> Any:
    """A `rejected` / `pending` `w1` (narrowed in the seed): neither writer reads the
    row's applicability, so each commits its baseline outcome as version 2 (history
    `[1, 2]`) and leaves the row in the state it was narrowed to."""

    def check(env: _G2Env, cell: _G2Cell, out: _G2Out, before: Any) -> None:
        assert out.body == expected, (cell.row_state, out.body)
        row = _r8_stored(env, "w1")
        assert (row["artifact_version"], row["applicability"]) == (
            2,
            cell.row_state,
        ), row
        assert env.store is not None
        with contextlib.closing(sqlite3.connect(env.store.db_path)) as conn:
            versions = [
                v
                for (v,) in conn.execute(
                    "SELECT artifact_version FROM memory_artifact_versions "
                    "WHERE artifact_id = 'w1' ORDER BY artifact_version"
                )
            ]
        gc.collect()
        assert versions == [1, 2], (cell.row_state, versions)

    return check


def _r8_tampered_write(key: str, recorded: Any) -> Any:
    """A `tampered` `w1`: exactly the baseline outcome (`_R8_EXACT[key]`)."""

    def check(env: _G2Env, cell: _G2Cell, out: _G2Out, before: Any) -> None:
        assert _g2_exact_body(env, out.body) == _R8_EXACT[key].body, out.body
        recorded(env, cell, out, before)

    return check


def _r8_writer_states(
    key: str, recorded: Any, expected: dict[str, Any]
) -> dict[str, _G2Expect]:
    """The `row_state` cells of a writer that reacts to the existing row: `tampered`
    (the cell every writer has) plus the narrowed ones; nothing beyond the store
    changes in any of them."""
    return {
        "tampered": _ex(None, committed=0, check=_r8_tampered_write(key, recorded)),
        **{
            state: _ex(None, committed=0, check=_r8_narrowed_write(expected))
            for state in _R8_NARROWED
        },
        **{
            state: _ex(None, committed=0, check=_r8_retired_write(expected))
            for state in ("archived", "expired")
        },
    }


def _r8_retired_write(expected: dict[str, Any]) -> Any:
    """An `archived` / `expired` `w1` (set in the seed): observed, neither writer reads
    the row's archive or expiry, so each commits its baseline outcome as version 2
    (history `[1, 2]`) and the new version keeps the row archived / expired."""

    def check(env: _G2Env, cell: _G2Cell, out: _G2Out, before: Any) -> None:
        assert out.body == expected, (cell.row_state, out.body)
        row = _r8_stored(env, "w1")
        retired = (1.0, None) if cell.row_state == "archived" else (None, 2.0)
        assert (
            row["artifact_version"],
            (row["archived_at"], row["expired_at"]),
            row["applicability"],
        ) == (2, retired, None), row
        assert env.store is not None
        with contextlib.closing(sqlite3.connect(env.store.db_path)) as conn:
            versions = [
                v
                for (v,) in conn.execute(
                    "SELECT artifact_version FROM memory_artifact_versions "
                    "WHERE artifact_id = 'w1' ORDER BY artifact_version"
                )
            ]
        gc.collect()
        assert versions == [1, 2], (cell.row_state, versions)

    return check


def _r8_module_routes() -> list[_G2Route]:
    reader_dims = {"store": _R8_STORE_NONE, "row_state": _R8_STATES_OK}
    version_dims = {
        "row_state": _r8_writer_states(
            "internal.intent_module-function-supersede_intent",
            _r8_superseded,
            _R8_SUPERSEDED_OK,
        ),
        "store": {
            "absent": _ex(None, committed=0, same=False, memory_same=False),
            "old_schema": _ex(None, same=False, memory_same=False),
        },
    }
    outcome_dims = {
        "row_state": _r8_writer_states(
            "internal.recipes-function-record_recipe_outcome",
            _r8_outcome_recorded,
            _R8_OUTCOME_OK,
        ),
        "store": {
            "absent": _ex(
                None,
                committed=0,
                same=False,
                memory_same=False,
                check=_r8_outcome_store,
            ),
            "old_schema": _ex(
                None,
                committed=0,
                same=False,
                memory_same=False,
                check=_r8_outcome_store,
            ),
        },
    }
    return [
        _r8_route(
            "intent_module",
            "check_intent",
            _r8_check_intent,
            supports=reader_dims,
            grant_sources=("intent:i1",),
            pre_setup=_r8_seed_intent,
            covers=(("memory/intent.py", "check_intent"),),
        ),
        _r8_route(
            "intent_module",
            "_resolve_authorized_statement",
            _r8_resolve_statement,
            ungated=frozenset(),
            pre_setup=_r8_seed_statement,
            supports={
                "row_state": {
                    s: _ex(None, check=_r8_statement_state)
                    for s in ("tampered", *_R8_NARROWED)
                },
                "store": {
                    "absent": _ex(None, same=False, memory_same=False),
                    "old_schema": _ex(None, same=False, memory_same=False),
                },
            },
            covers=(("memory/intent.py", "_resolve_authorized_statement"),),
        ),
        _r8_writer(
            "intent_module",
            "record_intent",
            "intent:w1",
            _r8_record_intent,
            covers=(("memory/intent.py", "record_intent"),),
        ),
        _r8_writer(
            "intent_module",
            "supersede_intent",
            "intent:w1",
            _r8_supersede,
            check=_r8_superseded,
            supports=version_dims,
            pre_setup=_r8_seed_superseding,
            covers=(("memory/intent.py", "supersede_intent"),),
        ),
        _r8_route(
            "recipes",
            "resolve_recipe",
            _r8_resolve_recipe,
            supports=reader_dims,
            grant_sources=("recipe:r1",),
            pre_setup=_r8_seed_recipe,
            covers=(("memory/recipes.py", "resolve_recipe"),),
        ),
        _r8_writer(
            "recipes",
            "record_recipe",
            "recipe:w1",
            _r8_record_recipe,
            covers=(("memory/recipes.py", "record_recipe"),),
        ),
        _r8_writer(
            "recipes",
            "record_recipe_outcome",
            "recipe:w1",
            _r8_recipe_outcome,
            check=_r8_outcome_recorded,
            supports=outcome_dims,
            pre_setup=_r8_seed_outcome,
            covers=(("memory/recipes.py", "record_recipe_outcome"),),
        ),
    ]


# --- maintenance and expiry (memory/maintenance.py, memory/expiry.py) ----------------


def _r8_seed_maint(env: _G2Env) -> None:
    """A `rejected` / `pending` row that both sweeps would visit: anchored to a symbol
    whose recorded hash is stale, and past its TTL."""
    state = env.extra["cell"].row_state
    if env.store is None or state not in _R8_NARROWED:
        return
    written = env.store.write(
        MemoryArtifact(
            id="mrow",
            family="memory",
            subject=SUBJECT,  # type: ignore[arg-type]
            trust_tier="DERIVED",
            content={"text": "needle mk-mrow"},
            source="source-a",
            created_at=1.0,
            symbol_ref="helper.py::helper",
            content_hash="stale",
            owner_scope=ALICE,
            applicability=state,
        )
    )
    assert written.artifact_version == 1 and written.applicability == state, written


def _r8_maint_access(env: _G2Env, cell: _G2Cell, *, apply: bool) -> Any:
    from rush.memory.retrieval import route_access

    return route_access(
        env.root,
        "maintain",
        apply=apply,
        session_allowlist=cell.allow,
        owner_scope=cell.owner,
    )


def _r8_preview(env: _G2Env, cell: _G2Cell) -> Any:
    from rush.memory.maintenance import preview_maintenance_candidates

    access = _r8_maint_access(env, cell, apply=False)
    if not hasattr(access, "project_root"):
        return _r8_denial_out(access)
    return preview_maintenance_candidates(
        "staleness_sweep", access=access, project_root=env.root
    )


def _r8_run(env: _G2Env, cell: _G2Cell) -> Any:
    from rush.memory.maintenance import run_maintenance_cycle

    access = _r8_maint_access(env, cell, apply=True)
    if not hasattr(access, "project_root"):
        return _r8_denial_out(access)
    return run_maintenance_cycle(
        "staleness_sweep", access=access, project_root=env.root
    )


def _r8_conn_call(env: _G2Env, cell: _G2Cell, fn: Any) -> Any:
    access = _r8_maint_access(env, cell, apply=True)
    if not hasattr(access, "project_root"):
        return _r8_denial_out(access)
    db = env.root / ".rush" / "memory.db"
    if not db.exists():
        return {"store": "absent"}
    with contextlib.closing(sqlite3.connect(db)) as conn:
        conn.row_factory = sqlite3.Row
        return fn(conn, access)


def _r8_conflicts(env: _G2Env, cell: _G2Cell) -> Any:
    from rush.memory.maintenance import _revision_conflicts

    return _r8_conn_call(
        env,
        cell,
        lambda conn, access: repr(
            _revision_conflicts(conn, {cell.target: 1}, access=access, root=env.root)
        ),
    )


def _r8_conflicts_narrowed(
    env: _G2Env, cell: _G2Cell, out: _G2Out, before: Any
) -> None:
    """A conflict is a version or scope mismatch only: the rejected/pending row at its
    reviewed version is found and reported clean (it is not hidden as "absent")."""
    assert out.body == "()", out.body
    assert _r8_stored(env, cell.target)["applicability"] == cell.row_state


def _r8_preview_narrowed(env: _G2Env, cell: _G2Cell, out: _G2Out, before: Any) -> None:
    assert [dict(c) for c in out.body] == [{"id": "mrow", "artifact_version": 1}]
    assert _r8_stored(env, "mrow")["applicability"] == cell.row_state


def _r8_run_narrowed(env: _G2Env, cell: _G2Cell, out: _G2Out, before: Any) -> None:
    """The sweep visits the stored row and marks it stale; the mark stays: the row is
    not made current again."""
    body = out.body
    assert (body.processed, body.changed, body.errors, body.refused) == (1, 1, (), ())
    assert body.unprocessed == () and not body.lock_lost, body
    stored = _r8_stored(env, "mrow")
    assert (stored["stale"], stored["artifact_version"]) == (1, 2), stored
    assert stored["applicability"] == cell.row_state, stored


def _r8_sweep_narrowed(env: _G2Env, cell: _G2Cell, out: _G2Out, before: Any) -> None:
    assert out.body == "(1, [])", out.body
    stored = _r8_stored(env, "mrow")
    assert (stored["expired_by"], stored["artifact_version"]) == ("expiry_sweep", 2)
    assert stored["applicability"] == cell.row_state, stored


def _r8_sweep(env: _G2Env, cell: _G2Cell) -> Any:
    from rush.memory.expiry import _sweep_reviewed_expired

    sweep_id = "mrow" if cell.row_state in _R8_NARROWED else "exp"
    return _r8_conn_call(
        env,
        cell,
        lambda conn, access: repr(
            _sweep_reviewed_expired(
                conn,
                access=access,
                renew=lambda ids: None,
                candidate_ids=[sweep_id],
                expected_revisions={sweep_id: 1},
            )
        ),
    )


def _r8_ran(env: _G2Env, cell: _G2Cell, out: _G2Out, before: Any) -> None:
    assert out.code is None and out.body is not None, (out.code, out.reason, out.body)


def _r8_ran_or_refused(env: _G2Env, cell: _G2Cell, out: _G2Out, before: Any) -> None:
    """Legacy access never reaches the sweep: the run is refused before any effect."""
    assert out.code in (None, "E_PERMISSION"), (out.code, out.reason)


def _r8_maintenance_routes() -> list[_G2Route]:
    maint = {
        "store": {
            "absent": _ex(None, "MemoryMigrationRequiredError", "OperationalError"),
            "old_schema": _ex(None, "MemoryMigrationRequiredError", "OperationalError"),
        },
        "row_state": {s: _ex(None, check=_r8_preview_narrowed) for s in _R8_NARROWED},
    }
    maint_run = {
        "store": {
            "absent": _ex(None, same=False, memory_same=False),
            "old_schema": _ex(None, same=False, memory_same=False),
        },
        "row_state": {
            s: _ex(None, same=False, memory_same=False, check=_r8_run_narrowed)
            for s in _R8_NARROWED
        },
    }
    conflicts_dims = {
        "row_state": {s: _ex(None, check=_r8_conflicts_narrowed) for s in _R8_NARROWED}
    }
    sweep_dims = {
        "row_state": {
            s: _ex(None, same=False, memory_same=False, check=_r8_sweep_narrowed)
            for s in _R8_NARROWED
        }
    }
    return [
        _r8_route(
            "maintenance_expiry",
            "preview_maintenance_candidates",
            _r8_preview,
            supports=maint,
            pre_setup=_r8_seed_maint,
            ok_codes=frozenset({None, "E_PERMISSION"}),
            takes_allowlist=True,
            takes_owner=True,
            grant_owner="alice",
            check_ok=_r8_ran,
            covers=(("memory/maintenance.py", "preview_maintenance_candidates"),),
        ),
        _r8_route(
            "maintenance_expiry",
            "run_maintenance_cycle",
            _r8_run,
            op="write",
            supports=maint_run,
            pre_setup=_r8_seed_maint,
            ok_codes=frozenset({None, "E_PERMISSION"}),
            takes_allowlist=True,
            takes_owner=True,
            grant_owner="alice",
            check_ok=_r8_ran,
            check_legacy=_r8_ran_or_refused,
            idempotent=False,
            covers=(("memory/maintenance.py", "run_maintenance_cycle"),),
        ),
        _r8_route(
            "maintenance_expiry",
            "_revision_conflicts",
            _r8_conflicts,
            op="write",
            supports=conflicts_dims,
            pre_setup=_r8_seed_maint,
            ok_codes=frozenset({None, "E_PERMISSION"}),
            takes_allowlist=True,
            takes_owner=True,
            grant_owner="alice",
            check_ok=_r8_ran,
            check_legacy=_r8_ran_or_refused,
            covers=(("memory/maintenance.py", "_revision_conflicts"),),
        ),
        _r8_route(
            "maintenance_expiry",
            "_sweep_reviewed_expired",
            _r8_sweep,
            op="write",
            supports=sweep_dims,
            pre_setup=_r8_seed_maint,
            ok_codes=frozenset({None, "E_PERMISSION"}),
            takes_allowlist=True,
            takes_owner=True,
            grant_owner="alice",
            check_ok=_r8_ran,
            check_legacy=_r8_ran_or_refused,
            covers=(("memory/expiry.py", "_sweep_reviewed_expired"),),
        ),
    ]


# --- the D4 gate helpers (memory/retrieval.py) ---------------------------------------


def _r8_access_out(access: Any) -> _G2Out:
    if hasattr(access, "reason"):
        return _G2Out(
            "E_INPUT" if access.reason == "source_pattern" else "E_PERMISSION",
            access.reason,
            frozenset(),
            0,
            {"denied": access.reason},
        )
    return _G2Out("OK", None, frozenset(), 0, {"kind": access.kind})


def _r8_authorize_writer(env: _G2Env, cell: _G2Cell) -> Any:
    from rush.memory.retrieval import authorize_writer

    with authorize_writer(env.root, _r8_source(cell), owner=cell.owner) as access:
        return _r8_access_out(access)


def _r8_source(cell: _G2Cell) -> str:
    return "source-x" if cell.row.endswith("source-ungranted") else "source-a"


def _r8_reader_route(env: _G2Env, cell: _G2Cell) -> Any:
    from rush.memory.retrieval import reader_route

    return _r8_access_out(reader_route(env.root, "ask", [_r8_source(cell)]))


def _r8_kind(kind: str):
    def check(env: _G2Env, cell: _G2Cell, out: _G2Out, before: Any) -> None:
        assert out.body == {"kind": kind}, out.body

    return check


def _r8_d4_routes() -> list[_G2Route]:
    return [
        _r8_route(
            "internal_d4",
            "authorize_writer",
            _r8_authorize_writer,
            op="write",
            takes_owner=True,
            coded=True,
            takes_allowlist=True,
            ok_codes=frozenset({"OK"}),
            grant_owner="alice",
            check_ok=_r8_kind("policy"),
            check_legacy=_r8_kind("legacy_allowlist"),
            owner_omitted_reason="owner_not_granted",
            covers=(("memory/retrieval.py", "authorize_writer"),),
        ),
        _r8_route(
            "internal_d4",
            "reader_route",
            _r8_reader_route,
            coded=True,
            takes_allowlist=True,
            ok_codes=frozenset({"OK"}),
            grant_owner="alice",
            check_ok=_r8_kind("policy"),
            check_legacy=_r8_kind("legacy_allowlist"),
            covers=(("memory/retrieval.py", "reader_route"),),
        ),
    ]


_G2_R8_ROUTES: tuple[_G2Route, ...] = (
    *_r8_mutation_routes(),
    *_r8_module_routes(),
    *_r8_maintenance_routes(),
    *_r8_d4_routes(),
)

_G2_ROUTES.extend(_G2_R8_ROUTES)
# 73-T02/BOOTSTRAP-CONSENT: `bind_store(overlay=True)` cells (D41 (b)), through the CLI.
_G2_BIND_ROWS = (
    "access-overlay-policy_state-ok-grant_ops-exact-apply-preview",
    "access-overlay-policy_state-ok-grant_ops-exact-apply-apply",
    "access-overlay-policy_state-ok-grant_ops-missing_one-apply-apply",
    "access-overlay-policy_state-ok-store-absent-apply-preview",
    "access-overlay-policy_state-ok-cache_write-off-apply-apply",
    "access-policy-policy_state-ok-grant_ops-exact-apply-preview",
    "access-policy-policy_state-ok-grant_ops-exact-apply-apply",
    "access-policy-policy_state-ok-store-absent-apply-preview",
    "access-legacy_allowlist-policy_state-missing_no_marker-apply-preview",
    "access-legacy_allowlist-policy_state-missing_no_marker-apply-apply",
    "access-policy-policy_state-missing_marker-apply-preview",
    "access-policy-policy_state-invalid-apply-apply",
)


def _g2_seed(root: Path, store: TypedArtifactStore, *, applicability: bool) -> None:
    """The fixture rows. `a1`/`a2` are Alice's active `source-a` rows, `x1` is hers under
    `source-x`, `arch` is archived, `exp` is expired and `tam` has tampered bytes. With
    `applicability` (the `row_state-rejected` / `row_state-pending` cells) `rej` is
    applicability-rejected and `pen` applicability-pending; every other cell's store
    carries neither, so the browse surfaces' exact row sets are unchanged."""
    for artifact_id, source in (
        ("a1", "source-a"),
        ("a2", "source-a"),
        ("x1", "source-x"),
        ("arch", "source-a"),
        ("exp", "source-a"),
        ("tam", "source-a"),
    ):
        _row(store, artifact_id, ALICE, f"mk-{artifact_id}", source=source)
    # the store writes (and MACs) the applicability, as the 72-T05 corrections do
    for artifact_id, state in (("rej", "rejected"), ("pen", "pending")):
        if applicability:
            _t05_row(
                store, artifact_id, ALICE, f"mk-{artifact_id}", applicability=state
            )
    store.archive(
        "arch", expected_version=1, scope=SUBJECT, owner_scope=ALICE, apply=True
    )
    with contextlib.closing(sqlite3.connect(store.db_path)) as conn:
        conn.execute(
            "UPDATE memory_artifacts SET expires_at = 1.0, expired_at = 2.0, "
            "expired_by = 'sweep' WHERE id = 'exp'"
        )
        conn.commit()
    _tamper(store.db_path, "tam")
    gc.collect()  # close the helpers' lingering connections: no -wal/-shm sidecars


def _g2_degrade_store(env: _G2Env, cell: _G2Cell) -> None:
    """`store-old_schema`: the same store, minus the columns only a write migrates in."""
    if cell.store == "old_schema" and env.store is not None:
        _drop_payload_columns(env.store.db_path)
        _no_sidecars(env.store.db_path)


def _g2_env(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch, route: _G2Route, row: str
) -> _G2Env:
    from rush.memory import authorization as auth

    data_root = default_data_root()
    root = _registered(tmp_path / "project", data_root)
    cell = _g2_parse_row(row)
    env = _G2Env(
        root=root,
        data_root=data_root,
        store=None,
        auth=auth,
        tmp_path=tmp_path,
        monkeypatch=monkeypatch,
        extra={"cell": cell, "transport": route.transport},
    )
    (root / "helper.py").write_text("def helper():\n    return 1\n", encoding="utf-8")
    if cell.store != "absent":
        env.store = TypedArtifactStore(root)
        _g2_seed(root, env.store, applicability=row.startswith(_G2_APPLICABILITY_ROWS))
    can_setup = route.setup is not None and cell.store != "absent"
    if route.pre_setup is not None:
        route.pre_setup(env)
    owner = ALICE if route.grant_owner == "alice" else legacy_owner_scope(root)
    ops = tuple(FULL_OPS_HISTORY)
    if "missing_no_marker" in row:
        if can_setup:
            route.setup(env)
        _g2_degrade_store(env, cell)
        return env
    sources: tuple[str, ...] = ("source-a",)
    if route.sourced and not row.endswith(("missing_one", "source-ungranted")):
        sources += (
            *(s(root) if callable(s) else s for s in route.grant_sources),
            *((route.writer_family,) if route.writer_family else ()),
        )
    if row.endswith("missing_marker"):
        # A registered-then-removed policy: the marker stays, the policy file goes.
        env.grant = _grant(auth, root, owner, data_root, sources=sources, ops=ops)
        if can_setup:
            route.setup(env)
        _g2_degrade_store(env, cell)
        auth.policy_path(data_root=data_root).unlink()
        return env
    env.grant = _grant(auth, root, owner, data_root, sources=sources, ops=ops)
    if can_setup:
        route.setup(env)
    _g2_degrade_store(env, cell)
    if row.endswith("grant-revoked"):
        auth.revoke_memory_scope(
            grant_id=env.grant["grant_id"],
            expected_policy_revision=_revision(auth, data_root),
            consent=True,
            data_root=data_root,
        )
    elif row.endswith("owner-omitted"):
        _grant(auth, root, BOB, data_root, ops=ops)
    elif row.endswith("policy_state-invalid"):
        auth.policy_path(data_root=data_root).write_bytes(b"{")
    elif row.endswith("missing_one"):
        lacking = set(route.missing_ops or (route.op,))
        reduced = tuple(o for o in ops if o not in lacking)
        _grant(auth, root, owner, data_root, ops=reduced)
    return env


def _g2_cells() -> list[Any]:
    cells = []
    for route in _G2_ROUTES:
        for row in _g2_rows(route):
            cells.append(pytest.param(route, row, id=f"{route.ident}-{row}"))
    for row in _G2_BIND_ROWS:
        cells.append(
            pytest.param(
                "bind_store_overlay",
                row,
                id=f"cli.cli_memory-operation-bind_store-function-overlay-{row}",
            )
        )
    return cells


_G2_DENIAL_REASONS = {
    "grant-revoked": "revoked",
    "owner-omitted": "owner_required",
    "policy_state-invalid": "policy_invalid",
    "missing_one": "operation_not_granted",
    "missing_marker": "policy_missing",
}


def _g2_effects(route: _G2Route, root: Path, data_root: Path) -> dict[str, Any]:
    """`_effects` without the paths the route's own constructor owns."""
    snapshot = _effects(root, data_root)
    if route.ignore_data:
        snapshot["data"] = {
            k: v
            for k, v in snapshot["data"].items()
            if not k.startswith(route.ignore_data)
        }
    if route.ignore_db:
        snapshot["db"] = None
        snapshot["counts"] = {}
        if snapshot.get("root"):
            snapshot["root"] = {
                k: v
                for k, v in snapshot["root"].items()
                if not k.startswith(".rush/memory.db")
            }
    if not route.ignore:
        return snapshot

    def keep(prefix: str):
        def test(key: str) -> bool:
            return not any(
                key == f"{prefix}{p.lstrip('=')}"
                or (not p.startswith("=") and key.startswith(f"{prefix}{p}/"))
                for p in route.ignore
            )

        return test

    if snapshot.get("root"):
        test = keep("")
        snapshot["root"] = {k: v for k, v in snapshot["root"].items() if test(k)}
    try:
        inside = root.resolve().relative_to(data_root.resolve()).as_posix() + "/"
    except ValueError:
        inside = None
    if inside is not None:
        test = keep(inside)
        snapshot["data"] = {k: v for k, v in snapshot["data"].items() if test(k)}
    return snapshot


def _g2_diff(before: dict[str, Any], after: dict[str, Any]) -> list[str]:
    """Which parts of an `_effects` snapshot differ, for assertion messages."""
    out: list[str] = []
    for part in ("root", "data"):
        old, new = before.get(part) or {}, after.get(part) or {}
        for key in sorted(set(old) | set(new)):
            if old.get(key) != new.get(key):
                out.append(f"{part}:{key}")
    for part in ("db", "counts"):
        if before.get(part) != after.get(part):
            out.append(part)
    return out


def _g2_denied(route: _G2Route, out: _G2Out) -> bool:
    """The route refused: an `E_PERMISSION` code, or (for a route that has no code)
    nothing revealed and nothing written."""
    if route.coded:
        return out.code == "E_PERMISSION"
    return not out.shown and out.committed == 0 and out.code in (None, "E_PERMISSION")


def _g2_assert_denied(
    route: _G2Route, row: str, out: _G2Out, reason: str | None
) -> None:
    detail = (route.ident, row, out.code, out.reason, sorted(out.shown), out.status)
    assert _g2_denied(route, out), detail
    if route.coded and reason is not None:
        assert out.reason == reason, detail
    assert not out.shown, detail
    assert out.committed == 0, detail


def _g2_call(route: _G2Route, env: _G2Env, cell: _G2Cell) -> _G2Out:
    count = _g2_count(env)
    out = route.call(env, cell)
    return dataclasses.replace(out, committed=_g2_count(env) - count)


def _g2_run_policy_row(route: _G2Route, row: str, env: _G2Env, cell: _G2Cell) -> None:
    before = _g2_effects(route, env.root, env.data_root)
    snapshot = _g2_snapshot(env)
    out = _g2_call(route, env, cell)
    detail = (route.ident, row, out.code, out.reason, sorted(out.shown), out.status)

    if route.custom_policy is not None:
        route.custom_policy(route, row, env, cell, out)
        assert _g2_effects(route, env.root, env.data_root) == before, detail
        return
    if route.ungated is not None:
        # Not memory-gated (it reads token events, not rows): the same answer in
        # every row, and it changes nothing.
        assert out.shown == route.ungated, detail
        assert _g2_effects(route, env.root, env.data_root) == before, detail
        return
    if row.endswith("owner-omitted") and route.owner_required:
        # The strict model requires `owner_scope` here: omitting it is an input error
        # with zero effects, never a silently defaulted owner.
        assert out.code in ("E_INPUT", "E_PERMISSION") or out.status == "error", detail
        assert _g2_effects(route, env.root, env.data_root) == before, detail
        return
    if row.endswith("owner-omitted") and route.key in ("link", "consolidate"):
        # 72-T03 R2 (AM8): the fixture holds Alice and Bob grants, so the owner is
        # required as an input error naming the field, with zero effects.
        assert out.code == "E_INPUT", detail
        assert _rd(out.body)["data"].get("field") == "owner_scope", detail
        assert _g2_effects(route, env.root, env.data_root) == before, detail
        return
    for suffix, expected in _G2_DENIAL_REASONS.items():
        if row.endswith("owner-omitted") and route.owner_fixed:
            break
        if suffix == "owner-omitted" and route.owner_omitted_reason is not None:
            expected = route.owner_omitted_reason
        if row.endswith(suffix):
            _g2_assert_denied(route, row, out, expected)
            after = _g2_effects(route, env.root, env.data_root)
            assert after == before, (
                f"{detail}: a denied route changed state {_g2_diff(before, after)}"
            )
            return
    if row.endswith("source-ungranted"):
        if route.ungranted is not None:
            assert out.code in route.ungranted.codes, detail
            assert not out.shown and out.committed == 0, detail
            assert _g2_effects(route, env.root, env.data_root) == before, detail
        elif route.takes_allowlist or route.sourced:
            _g2_assert_denied(route, row, out, "source_not_granted")
            assert _g2_effects(route, env.root, env.data_root) == before, detail
        else:
            assert out.code in route.ok_codes or out.code == "E_INPUT", detail
            assert out.reason not in POLICY_REASONS, detail
        return
    if "missing_no_marker" in row:
        # Legacy mode keeps the HEAD behavior: never a policy denial.
        assert out.reason not in POLICY_REASONS, detail
        assert out.code in route.ok_codes or out.code in (None, "E_INPUT"), detail
        if route.check_legacy is not None:
            route.check_legacy(env, cell, out, snapshot)
        return
    # policy + exact grant: the route reached its own outcome, exactly.
    assert out.code in route.ok_codes, detail
    assert out.reason not in POLICY_REASONS, detail
    if route.check_ok is not None:
        route.check_ok(env, cell, out, snapshot)


def _g2_run_overlay_row(route: _G2Route, row: str, env: _G2Env, cell: _G2Cell) -> None:
    """Access form `overlay`. A route with an `owner_scope` input is
    sent the user-overlay owner: no overlay grant exists yet, so it refuses with
    `owner_not_granted`. A route with no owner input is pointed at the overlay storage
    root instead, which is never a project route (`overlay_storage_root`)."""
    overlay = env.auth.user_overlay_owner_scope(data_root=env.data_root)
    if route.ungated is not None:
        return
    if route.custom_policy is not None:
        target = Path(overlay.id)
        target.mkdir(parents=True, exist_ok=True)
        env = dataclasses.replace(env, root=target)
        before = _g2_effects(route, target, env.data_root)
        out = _g2_call(route, env, cell)
        route.custom_policy(route, row, env, cell, out)
        assert _g2_effects(route, target, env.data_root) == before
        return
    mutation = False
    if route.takes_owner:
        before = _g2_effects(route, env.root, env.data_root)
        out = _g2_call(route, env, dataclasses.replace(cell, owner=overlay))
        reason = "owner_not_granted"
        # 72-T05 D25: only the preference route writes personal content, so a
        # content mutation refuses the overlay owner with `E_OWNER` before any grant.
        mutation = route.key in _G2_OVERLAY_MUTATIONS or any(
            name in route.cell for name in ("memory_edit", "memory_maintain")
        )
        target = env.root
    else:
        target = Path(overlay.id)
        target.mkdir(parents=True, exist_ok=True)
        env = dataclasses.replace(env, root=target)
        if route.transport in ("dashboard", "tui"):
            # these readers address a project by id: the registration is fixture
            # setup (their only effect), taken before the baseline
            _g2_project_id(env)
        if route.overlay_setup is not None:
            route.overlay_setup(env)
        before = _g2_effects(route, target, env.data_root)
        out = _g2_call(route, env, cell)
        reason = "overlay_storage_root"
    detail = (route.ident, row, out.code, out.reason, sorted(out.shown), out.status)
    if mutation:
        assert out.code == "E_OWNER", detail
        assert out.reason == "overlay_requires_preference_route", detail
    else:
        assert _g2_denied(route, out), detail
        if route.coded:
            assert out.reason == reason, detail
    assert not out.shown and out.committed == 0, detail
    assert _g2_effects(route, target, env.data_root) == before, detail


_G2_OVERLAY_MUTATIONS = frozenset(
    {"write", "promote", "edit", "link", "consolidate", "maintain"}
)


def _g2_run_dim_row(route: _G2Route, row: str, env: _G2Env, cell: _G2Cell) -> None:
    dim, value = _g2_split(row)
    expect: _G2Expect = route.supports[dim][value]
    before = _g2_effects(route, env.root, env.data_root)
    snapshot = _g2_snapshot(env)
    out = _g2_call(route, env, cell)
    detail = (route.ident, row, out.code, out.reason, sorted(out.shown), out.status)
    assert out.code in expect.codes, detail
    if expect.status is not None:
        assert out.status == expect.status, detail
    assert expect.show <= out.shown, detail
    if expect.exact is not None:
        assert out.shown == expect.exact, detail
    assert not (expect.hide & out.shown), detail
    if expect.committed is not None:
        assert out.committed == expect.committed, detail
    after = _g2_effects(route, env.root, env.data_root)
    if expect.same:
        assert after == before, f"{detail}: effects changed {_g2_diff(before, after)}"
    elif expect.memory_same:
        assert after["db"] == before["db"], f"{detail}: memory.db changed"
    for rel in expect.absent:
        assert not (env.root / rel).exists(), f"{detail}: {rel} created"
    if expect.check is not None:
        expect.check(env, cell, out, snapshot)


_G2_VOLATILE = re.compile(
    r'("[a-z_]*(?:_ms|_at|_time|timestamp|duration|elapsed|ts)[a-z_]*"\s*:\s*)'
    r"[-+0-9.eE]+|0x[0-9a-f]+"
)


def _g2_normal_body(value: Any) -> str:
    """A route's whole response body with the volatile fields (durations, timestamps,
    object addresses) neutralized, for the byte-identity comparison."""
    return _g2_neutralize_volatile(json.dumps(value, sort_keys=True, default=repr))


def _g2_neutralize_volatile(text: str) -> str:
    return _G2_VOLATILE.sub(lambda m: f"{m.group(1)}0" if m.group(1) else "0x0", text)


@dataclasses.dataclass(frozen=True)
class _G2Exact:
    """A non-idempotent route's whole outcome on a cell whose dimension it does not
    vary along: the `_g2_diff` entries it changes (uuid path segments as `<id>`), its
    `(code, reason, status, shown, committed)`, and its whole normalized body."""

    effects: frozenset[str]
    out: tuple[Any, ...]
    body: str


_G2_EXACT_UUID = re.compile(
    r"[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}"
)
# Values minted per run (timestamps, ids, digests over them, session secrets),
# replaced in this order after the root/data-root paths and the token and `_G2_VOLATILE` passes.
_G2_EXACT_VOLATILE = (
    (
        re.compile(r"\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d(?:\.\d+)?(?:[+-]\d\d:\d\d|Z)?"),
        "<iso>",
    ),
    (_G2_EXACT_UUID, "<id>"),
    (re.compile(r"(?<![0-9a-f])[0-9a-f]{64}(?![0-9a-f])"), "<sha>"),
    (re.compile(r"(?<![0-9a-f])[0-9a-f]{32}(?![0-9a-f])"), "<hex>"),
    (re.compile(r"(?<![\w.])1[0-9]{9}\.[0-9]+"), "<t>"),
)
# A minted 43-character urlsafe token, replaced before `_G2_VOLATILE` runs: that pass
# rewrites any `0x<hex>` run, so a token containing one would no longer be 43 long.
_G2_EXACT_TOKEN = re.compile(r"(?<![A-Za-z0-9_-])[A-Za-z0-9_-]{43}(?![A-Za-z0-9_-])")


def _g2_exact_body(env: _G2Env, body: Any) -> str:
    text = (
        json.dumps(body, sort_keys=True, default=repr)
        .replace(str(env.root), "<root>")
        .replace(str(env.data_root), "<data>")
    )
    text = _g2_neutralize_volatile(_G2_EXACT_TOKEN.sub("<token>", text))
    for pattern, label in _G2_EXACT_VOLATILE:
        text = pattern.sub(label, text)
    return text


def _g2_assert_writer_exact(
    route: _G2Route,
    env: _G2Env,
    out: _G2Out,
    before: dict[str, Any],
    after: dict[str, Any],
    detail: Any,
) -> None:
    """spec-tests-3/security-8: a non-idempotent route's unsupported cell has exactly
    its declared effects (nothing beyond them, project or data root) and exactly its
    declared output, so a write plus a stray file or a foreign row's output fails."""
    exact = _G2_WRITER_EXACT.get(route.ident)
    assert exact is not None, f"{route.ident}: no exact unsupported-cell oracle"
    effects = frozenset(_G2_EXACT_UUID.sub("<id>", d) for d in _g2_diff(before, after))
    assert effects == exact.effects, (*detail, sorted(effects ^ exact.effects))
    shape = (out.code, out.reason, out.status, tuple(sorted(out.shown)), out.committed)
    assert shape == exact.out, (*detail, shape, exact.out)
    assert _g2_exact_body(env, out.body) == exact.body, detail


