# =============================================================================
# T01 matrix extensions owned by 73-T02/BOOTSTRAP-CONSENT
# =============================================================================
#
# `bind_store(overlay=True)` is produced here (D41 (b)); the T01 producer cells flip to
# the outcomes below and `test_t01_existing_apply_and_historical_are_real_cells` gains
# the consent approve cells.


def _bind_overlay_denial(row: str) -> tuple[str, str] | None:
    """The item 7 denial of one bind-store overlay row, or None when it is allowed."""
    if "grant_ops-missing_one" in row:
        return ("E_PERMISSION", "operation_not_granted")
    if row.startswith("access-legacy_allowlist") or "missing_marker" in row:
        return ("E_PERMISSION", "policy_missing")
    if "policy_state-invalid" in row:
        return ("E_PERMISSION", "policy_invalid")
    if row.startswith("access-policy-policy_state-ok"):
        return ("E_OWNER", "owner_not_granted")
    return None


def _g2_bind_overlay_cell(row: str, tmp_path: Path) -> None:
    from rush.memory import authorization as auth
    from rush.memory.retrieval import required_operation_set

    consent = _k_cli()
    data_root = default_data_root()
    overlay = auth.user_overlay_owner_scope(data_root=data_root)
    root = _registered(tmp_path / "project", data_root)
    apply = row.endswith("apply-apply")
    if row.startswith("access-overlay"):
        ops: tuple[str, ...] = ("overlay_read", "list", "expand", "write")
        if "grant_ops-missing_one" in row:
            ops = ("overlay_read", "list", "expand")
        _grant(auth, root, overlay, data_root, sources=(OVERLAY_SOURCE,), ops=ops)
    elif row.startswith("access-policy"):
        _grant(auth, root, ALICE, data_root, ops=FULL_OPS_HISTORY)
        if "missing_marker" in row:
            auth.policy_path(data_root=data_root).unlink()
        elif "policy_state-invalid" in row:
            auth.policy_path(data_root=data_root).write_bytes(b"{")
    overlay_root = data_root / "user"
    overlay_root.mkdir(parents=True, exist_ok=True)
    if "store-absent" in row:
        digest = "0" * 64
    else:
        consent._c_unbound_stated(overlay_root, "p1", OVERLAY_SOURCE, owner=overlay)
        digest = TypedArtifactStore.bind_store(overlay_root, approve=False)[
            "binding_digest"
        ]
    args = ["memory", "bind-store", "--project", str(root), "--overlay"]
    if apply:
        args += ["--approve", "--expected-digest", digest]
    before = consent._c_state(root, overlay_root)
    if "cache_write-off" in row:
        consent._c_skipped(args, "bind_store")
        assert consent._c_state(root, overlay_root) == before
        return
    if apply:
        args.append("--allow-cache-write")
    operations = required_operation_set(
        "write" if apply else "list", apply=apply, overlay=True
    )
    expected = _bind_overlay_denial(row)
    if expected is not None:
        code, reason = expected
        payload = consent._c_run(args, code=code)
        assert payload["raw"]["data"]["reason"] == reason, payload["raw"]
        nxt = auth.memory_next_action(
            reason=reason,
            project_root=root,
            operations=operations,
            owner_scope=overlay,
        )
        assert payload["raw"]["next_action"] == nxt
        if reason != "policy_invalid":
            assert "--overlay" in str(nxt["command"])
        assert consent._c_state(root, overlay_root) == before
        return
    if "store-absent" in row:
        payload = consent._c_run(args, code="OK")
        assert payload["raw"]["data"]["store"] == "absent"
        assert consent._c_state(root, overlay_root) == before
        return
    payload = consent._c_run(args, code="OK")
    if apply:
        assert consent._c_binding(overlay_root) == "bound"
    else:
        assert payload["raw"]["data"]["store_binding"] == "unbound"
        assert consent._c_state(root, overlay_root) == before


def _consent_approve_cells() -> list[tuple[str, Any, dict[str, str], tuple[Any, ...]]]:
    approve_rows = {
        "grant_approve",
        "revoke_approve",
        "bind_approve",
        "bind_overlay_apply",
        "connect_bind_approve",
    }
    out = []
    for param in _k_cells():
        runner, dims, rest = param.values
        if _k_row(param.id) in approve_rows and "refuse" not in dims:
            out.append((param.id, runner, dims, rest))
    return out


def _k_row(ident: str) -> str:
    """The consent row of a cell id: `cli.cli_memory-operation-<row>-...`."""
    body = ident.split(".", 1)[1].removeprefix("cli_memory-operation-")
    return body.split("-", 1)[0]


T03_ENCODING = "cl100k_base"


def _t03_sub(tmp_path: Path, name: str) -> Path:
    path = tmp_path / name
    path.mkdir()
    return path


def _t03_count(
    store: TypedArtifactStore, table: str = "memory_artifacts", where: str = "1 = 1"
) -> int:
    with contextlib.closing(sqlite3.connect(store.db_path)) as conn:
        return int(
            conn.execute(f"SELECT COUNT(*) FROM {table} WHERE {where}").fetchone()[0]
        )


def _t03_summary_ids(store: TypedArtifactStore) -> list[str]:
    with contextlib.closing(sqlite3.connect(store.db_path)) as conn:
        rows = conn.execute("SELECT id, content FROM memory_artifacts").fetchall()
    return sorted(r[0] for r in rows if "consolidated_episode_summary" in r[1])


def _t03_legacy_store(tmp_path: Path, name: str = "legacy") -> TypedArtifactStore:
    return TypedArtifactStore(_t03_sub(tmp_path, name).resolve())


def _t03_ep(
    store: TypedArtifactStore,
    artifact_id: str,
    owner: OwnerScope | None,
    *,
    source: str = "source-a",
    **extra: Any,
) -> MemoryArtifact:
    return _row(
        store,
        artifact_id,
        owner,
        "",
        source=source,
        subject="episodic",
        content=_t03_episode(**extra),
    )


def _t03_grant_with_expiry(
    auth: Any, root: Path, data_root: Path, expires: float
) -> dict[str, Any]:
    return auth.grant_memory_scope(
        project_root=root,
        owner_scope=ALICE,
        approved_sources=list(T03_ALICE_SOURCES),
        allowed_operations=list(T03_ALICE_OPS),
        expected_policy_revision=_revision(auth, data_root),
        consent=True,
        expires_at=expires,
        data_root=data_root,
    )


def _t03_on_relation_insert(
    monkeypatch: pytest.MonkeyPatch, action: Any
) -> dict[str, int]:
    """Run `action()` once, when the `memory_relations` INSERT starts: after
    admission and inside the write transaction, before the commit."""
    from rush.memory import relations

    original = relations._connect
    fired = {"n": 0}

    def wrapper(store: Any) -> Any:
        conn = original(store)

        def trace(sql: str) -> None:
            if (
                sql.lstrip().startswith("INSERT INTO memory_relations")
                and not fired["n"]
            ):
                fired["n"] += 1
                try:
                    action()
                except BaseException as exc:  # noqa: BLE001 - a trace callback swallows errors
                    fired["error"] = repr(exc)  # type: ignore[assignment]

        conn.set_trace_callback(trace)
        return conn

    monkeypatch.setattr(relations, "_connect", wrapper)
    return fired


def _t03_after_summary_insert(
    monkeypatch: pytest.MonkeyPatch, action: Any
) -> dict[str, int]:
    """Run `action()` once, right after the consolidation summary row is inserted
    through `TypedArtifactStore._insert_row` (inside its transaction, before commit)."""
    original = TypedArtifactStore._insert_row
    fired = {"n": 0}

    def wrapper(self: Any, conn: Any, stored: Any, *args: Any, **kwargs: Any) -> Any:
        result = original(self, conn, stored, *args, **kwargs)
        content = stored.content if isinstance(stored.content, dict) else {}
        if content.get("kind") == "consolidated_episode_summary" and not fired["n"]:
            fired["n"] += 1
            action()
        return result

    monkeypatch.setattr(TypedArtifactStore, "_insert_row", wrapper)
    return fired


