    snapshot = _digest_dir(m.root)
    out = handler("related", {"id": "m1", "version": 1})
    assert out["code"] == "E_PERMISSION", out  # 72-T01 D22: the seed must be selected
    assert _digest_dir(m.root) == snapshot


